#include <iostream>
#include <vector>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<long long> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    int left = 0;
    int right = n - 1;
    long long sum_left = a[left];
    long long sum_right = a[right];
    int operations = 0;

    while (left < right) {
        if (sum_left == sum_right) {
            left++;
            right--;
            sum_left = a[left];
            sum_right = a[right];
        } else if (sum_left < sum_right) {
            left++;
            sum_left += a[left];
            operations++;
        } else {
            right--;
            sum_right += a[right];
            operations++;
        }
    }

    cout << operations << "\n";

    return 0;
}
